-- ---------------------------------------------------------------------------
-- Local testing only: every account can use every pack.
--
-- Ownership is enforced in the database (`board_can_use`, `set_board_theme`,
-- `place_magnet`), so the app cannot bypass it. Grant a promo entitlement for
-- every non-bundle pack to every profile, and to every profile created later.
-- `seed.sql` never runs on `db push`, so this stays off the hosted project.
-- Undo with: delete from public.user_entitlements where source = 'promo';
-- ---------------------------------------------------------------------------

insert into public.user_entitlements (user_id, pack_id, source)
select p.id, pc.id, 'promo'
from public.profiles p
cross join public.pack_catalog pc
where pc.kind <> 'bundle'
on conflict (user_id, pack_id) do update set revoked_at = null;

create or replace function public.dev_grant_all_packs()
returns trigger
language plpgsql
security definer
set search_path = '' as $$
begin
  insert into public.user_entitlements (user_id, pack_id, source)
  select new.id, pc.id, 'promo'
  from public.pack_catalog pc
  where pc.kind <> 'bundle'
  on conflict (user_id, pack_id) do update set revoked_at = null;
  return new;
end;
$$;

drop trigger if exists dev_grant_all_packs on public.profiles;
create trigger dev_grant_all_packs
after insert on public.profiles
for each row execute function public.dev_grant_all_packs();
